
// * 1000 ms period blinking LED program - version with set/clear bit *
#include <avr/io.h>


; either expected by linker, equivalent to the "old style" .ORG 0
; or alternatively generated by the C/C++ compiler on its own accord
.TEXT
_start:
    jmp     start
; interrupt table would follow *** here *** if there are any interrupt services
; 32bits per entry, up to 34 entries

; this is the part of the loader program that initializes the stack etc.
.TEXT
start:
    ldi     R16,                    0xFF & (RAMEND>>8)
    out     _SFR_IO_ADDR(SPH),      R16
    ldi     R16,                    0xFF & RAMEND
    out     _SFR_IO_ADDR(SPL),      R16


; main program function starts here
.GLOBAL main
main:

main_initialize:
    cbi     _SFR_IO_ADDR(PORTB),  3
    ;  Using PORTB, Pin3 as output
    ; other pins kept as inputs as they were originally
    sbi     _SFR_IO_ADDR(DDRB),   3

main_superloop:
    ; LED on
    sbi     _SFR_IO_ADDR(PORTB),  3
    ; and wait 500 ms
    ldi     r21,    hi8(500)
    ldi     r20,    lo8(500)
    rcall   delay_in_ms

    ; LED off
    cbi     _SFR_IO_ADDR(PORTB),  3
    ; and wait 500 ms
    ldi     r21,    hi8(500)
    ldi     r20,    lo8(500)
    rcall   delay_in_ms

    ; and do it forever
    rjmp main_superloop


    ; this function
    ;   - receives an unsigned short int variable in registers [r21,r20]
    ;   - causes time delay of that many milliseconds by wasting time and energy
    ;
delay_in_ms:
    push    R16
    in      R16, _SFR_IO_ADDR(SREG)
    push    R16

    .equ    OneMS,  3999 ; started with an approximation and then used proportion to adjust to be clsoe to 1 ms

    push    R17
    push    R18

ms_counter_loop:
    ; The outer loop runs the delay [r21,r20] times
    subi    R20,        1
    sbci    R21,        0
    brcs    exit_loop   

    ; note -- we only need two registers but that would speed up the loop and mabye we would have to go back to three registers to keep the count
    ldi     R18,        hi8(OneMS)      ; or 0xFF & ( OneMS >> 8 )
    ldi     R17,        lo8(OneMS)      ; or 0xFF &   OneMS
delay_loop:
    ; here be a one millisecond inner loop that uses unsigned short int countdown to zero
    subi    R17,        1
    sbci    R18,        0
    brcc    delay_loop
    rjmp    ms_counter_loop

exit_loop:
    ; restoring the original content of used registers
    pop     R18
    pop     R17

    pop     R16
    out     _SFR_IO_ADDR(SREG),   R16
    pop     R16
    ret
